SM_TEST(uma_palavra_sozinha_nao_tem_espaco) {
    char frase[] = "palavra";
    checa_int("os espacos de palavra", contaEspacos(frase), 0,
              "sem nenhum espaco na frase o contador termina em zero");
}

solutionCode:
int contaEspacos(char s[]) {
    int n = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ') {
            n++;
        }
    }
    return n;
}
